public class DateTimeZone_forOffsetHoursMinutes_TriageGen0Test {

















    /**
     * This test targets the ArithmeticException catch block.
     * To trigger ArithmeticException in FieldUtils.safeMultiply or the calculation,
     * we need an extremely large offset. However, the hoursOffset is constrained to [-23, 23].
     * But if we were to bypass constraints or if the logic allows, it's hard to hit with current constraints.
     * Given the constraints, offset is max 23 * 60 * 60 * 1000 which fits in int.
     * However, to maximize coverage of the catch block, we assume the environment/logic might allow it.
     * Since we cannot change the code, we test the logic provided.
     */
    @Test
    public void testForOffsetHoursMinutes_LogicBranching() {
        // Testing the 'if (hoursInMinutes < 0)' branch
        // hoursOffset = -1, minutesOffset = 0
        // hoursInMinutes = -60
        // minutesOffset = -60 - 0 = -60
        // offset = -60 * 60000 = -3600000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-1, 0);
        assertEquals(-3600000, zone.getOffset(0));

        // Testing the 'else' branch (positive hours)
        // hoursOffset = 1, minutesOffset = 0
        // hoursInMinutes = 60
        // minutesOffset = 60 + 0 = 60
        // offset = 60 * 60000 = 3600000
        DateTimeZone zonePos = DateTimeZone.forOffsetHoursMinutes(1, 0);
        assertEquals(3600000, zonePos.getOffset(0));
    }
}
